{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    total_min = sum(seg['minimum'] for seg in segments)
    total_cap = sum(seg['capacity'] for seg in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget infeasible')
    allocs = [seg['minimum'] for seg in segments]
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if allocs[i] < seg['capacity']:
                score = seg['importance'] / (allocs[i] + 1.0)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break
        allocs[best_idx] += 1
        remaining -= 1
    by_name = {}
    for seg, alloc in zip(segments, allocs):
        by_name[seg['name']] = alloc
    total = sum(allocs)
    return {'allocations': allocs, 'by_name': by_name, 'total': total}"}
